 "content": "def transform(grid):
    """Restore cells obscured by 3 using the row's left-right symmetry."""
    out = [row[:] for row in grid]
    width = len(grid[0])
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value == 3:
                out[r][c] = row[width - 1 - c]
    return out
